import {columnVolumeT0,compare} from '../rules.mjs';
import {flowOf,runColumn} from '../data-model/derive.mjs';
export const G_SOURCE='GRADIENT Discovery Book §1.4; Cycle 4 Gradient ED feedback 260918 slides 7, 10–14, 21, 28–29; Dolan 2013 Dwell-Volume Problems';
const pos=x=>Number.isFinite(x)&&x>0,nonneg=x=>Number.isFinite(x)&&x>=0;
export function gradientSteepness({Vm,initialB,finalB,F,tG}){if(![Vm,F,tG].every(pos)||!Number.isFinite(initialB)||!Number.isFinite(finalB)||initialB<0||finalB>100||finalB<=initialB)return {ok:false,reason:'Need positive column mobile volume, flow, ramp time and 0 ≤ initial %B < final %B ≤ 100.'};const delta=(finalB-initialB)/100;return {ok:true,delta,GS:Vm*delta/(F*tG),slopePercentPerMin:(finalB-initialB)/tG};}
export function gradientProgram(p){const z=gradientSteepness(p);if(!z.ok||![p.initialHold,p.finalHold,p.returnTime,p.equilTime].every(nonneg))return {ok:false,reason:z.reason||'Hold, return and equilibration times must be recorded and non-negative.'};
 const h=p.initialHold,end=h+p.tG,flush=end+p.finalHold,back=flush+p.returnTime,total=back+p.equilTime,pump=[[0,p.initialB],[h,p.initialB],[end,p.finalB],[flush,p.finalB],[back,p.initialB],[total,p.initialB]],delay=nonneg(p.dwellVolume)?p.dwellVolume/p.F:null;
 return {...z,ok:true,pump,inlet:delay===null?null:[[0,p.initialB],...pump.map(([t,b])=>[t+delay,b])],dwellTime:delay,totalTime:total,totalAtInlet:delay===null?null:total+delay};}
export function preserveGS(old,next){const a=gradientSteepness(old);if(!a.ok)return {ok:false,reason:a.reason};const z={...old,...next};if(!pos(z.Vm)||!pos(z.F)||!(z.finalB>z.initialB))return {ok:false,reason:'Invalid transferred gradient conditions.'};z.tG=z.Vm*((z.finalB-z.initialB)/100)/(z.F*a.GS);return {...z,...gradientSteepness(z),oldGS:a.GS};}
export function gradientAnalysis(s,r,d){const cfg=s.settings.course?.gradient||{},m=runColumn(s,r).model,F=cfg.F===undefined?flowOf(r):cfg.F,vol=columnVolumeT0(m?.lengthMm,m?.idMm,F),Vm=cfg.Vm==null&&vol.ok?vol.volume:cfg.Vm,actual=r.conditions.mode?.value==='GRA',named=r.profileExtras?.gradient,pick=(k,def)=>cfg[k]===undefined?(named?.[k]??def):cfg[k],
 p={Vm,initialB:pick('initialB',5),finalB:pick('finalB',100),tG:pick('tG',20),F,initialHold:pick('initialHold',2),finalHold:pick('finalHold',3),returnTime:pick('returnTime',1),equilTime:pick('equilTime',2),dwellVolume:cfg.dwellVolume??null},program=gradientProgram(p),target=s.settings.specs.peakCount.value;
 const out={...p,program,actual,VmEstimated:cfg.Vm==null,source:G_SOURCE,scope:'Starter: GS arithmetic and a planned program, not predicted compound tR, pressure profile or Rs. Isocratic minimum is not assigned as the gradient start. Dwell volume differs from column mobile volume. '+(actual&&!named?'Actual gradient range/ramp not recorded in the supported name: displayed scouting defaults are plans, not a reconstruction of acquisition.':'Named range/ramp, if present, is read from the selected run-name source; wash and holds remain planning inputs.')};
 if(!program.ok)return {...out,status:'GRADIENT INPUT',action:program.reason};
 if(!actual)return {...out,status:'SCOUTING PLAN',action:'Optional gradient scouting: '+p.initialB+'–'+p.finalB+' %B in '+p.tG+' min at '+p.F+' mL/min. Confirm wash/equilibration and dwell volume before running.'};
 if(d.n>target)return {...out,status:'OBSERVE',action:'Review blank and integration before optimising the gradient; peaks are not removed automatically.'};
 if(d.n<target)return {...out,status:'GRADIENT SELECTIVITY',action:'OBSERVE a changed GS: compare tG or F first, then the %B window. Measure peak count and spacing; no missing peak or Rs is predicted.'};
 if(compare(d.last,s.settings.specs.lastPeak.op,s.settings.specs.lastPeak.value).pass&&compare(d.rs,s.settings.specs.minRs.op,s.settings.specs.minRs.value).pass)return {...out,status:'MET',action:'MET for measured gradient peak count, last tR and Rs. Compare wash, equilibration and total cycle time separately.'};
 return {...out,status:'GRADIENT OBSERVE',action:'Compare a coupled F / tG change. Keeping GS requires Vm·Δφ/(F·tG) unchanged; changing tG alone at fixed F changes GS. Measure the critical-pair separation again.'};
}
